// Browser-only: intake.csv is read locally, cleaned in memory, downloaded.
// No server involved.
async function sanitiseFile(file: File): Promise<Blob> {
  const text = await file.text();
  const rows = parseCSV(text);
  const cleaned = rows.map(validateRow);
  return new Blob([toCSV(cleaned)], { type: "text/csv" });
}
